<template><AppShell><AsyncState :loading="loading" :error="error" :empty="!task.taskId" empty-text="未找到该任务" @retry="load"><header class="task-head"><span class="status-pill" :class="task.status">{{ statusText }}</span><h1>{{ selected?.title||task.title||'资源任务' }}</h1><p>{{ resourceTypeName(selected?.type||task.taskType) }} · {{ formatDate(task.updatedAt||task.createdAt) }}</p></header>
  <section v-if="!isTerminal" class="task-progress-panel"><div><span v-if="isActive" class="spinner"></span><CircleAlert v-else :size="20" /><div><strong>{{ progressTitle }}</strong><small>{{ task.result?.message||task.result?.currentStage||'后台任务状态已保存' }}</small></div><b>{{ taskProgress(task) }}%</b></div><div class="progress-track"><i :style="{width:`${taskProgress(task)}%`}"></i></div><button v-if="task.status==='waiting'&&task.taskType==='generated_video'" class="primary-btn full-btn" :disabled="starting" @click="startVideo"><Play :size="17" />{{ starting?'正在启动':'确认启动 AI 视频生成' }}</button></section>
  <template v-if="resources.length"><div v-if="resources.length>1" class="chip-row resource-tabs"><button v-for="(resource,i) in resources" :key="i" :class="{active:i===selectedIndex}" @click="select(i)">{{ resourceTypeName(resource.type) }} {{ i+1 }}</button></div><ResourceRenderer :resource="selected" />
    <section class="feedback-panel"><div class="section-head"><div><h2>学习反馈</h2><p>用于更新掌握度和后续路径</p></div><CheckCircle2 v-if="feedbackSaved" :size="22" /></div><div class="rating-row"><button v-for="n in 5" :key="n" :class="{active:rating>=n}" @click="rating=n"><Star :size="21" /></button></div><textarea v-model.trim="note" rows="3" placeholder="记录收获、疑问或需要加强的内容"></textarea><p v-if="feedbackError" class="form-error">{{ feedbackError }}</p><button class="primary-btn full-btn" :disabled="feedbackSaving||!rating||feedbackSaved" @click="saveFeedback">{{ feedbackSaved?'已记录':'完成学习并提交反馈' }}</button></section>
  </template><section v-else-if="task.status==='complete'" class="state-block"><strong>任务已完成，但返回结构中没有可预览资源。</strong></section>
  <div v-if="task.status==='failed'" class="failure-panel"><CircleAlert :size="23" /><div><strong>生成失败</strong><p>{{ task.error||'智能体任务未成功完成，请重新创建。' }}</p></div><RouterLink class="secondary-btn" to="/resources/new">重新生成</RouterLink></div>
  </AsyncState></AppShell></template>
<script setup>
import { computed,onBeforeUnmount,onMounted,ref } from 'vue';import { useRoute,useRouter,RouterLink } from 'vue-router';import { CheckCircle2,CircleAlert,Play,Star } from 'lucide-vue-next';import AppShell from '../components/AppShell.vue';import AsyncState from '../components/AsyncState.vue';import ResourceRenderer from '../components/ResourceRenderer.vue';import { getFeedback,getTask,startVideoTask,submitFeedback } from '../services/api.js';import { formatDate,resourceTypeName,taskFromPayload,taskProgress,taskResources,TERMINAL_TASK_STATES } from '../utils/data.js';import { trackTask } from '../stores/tasks.js'
const route=useRoute(),router=useRouter();const task=ref({}),loading=ref(true),error=ref(''),selectedIndex=ref(Number(route.params.itemIndex||0)),starting=ref(false),rating=ref(0),note=ref(''),feedbackSaving=ref(false),feedbackSaved=ref(false),feedbackError=ref('');let timer=0
const resources=computed(()=>taskResources(task.value));const selected=computed(()=>resources.value[selectedIndex.value]||resources.value[0]||null);const isTerminal=computed(()=>TERMINAL_TASK_STATES.has(task.value.status));const isActive=computed(()=>['queued','running'].includes(task.value.status));const statusText=computed(()=>({queued:'排队中',running:'生成中',complete:'已完成',failed:'失败',waiting:'等待确认',cancelled:'已取消'}[task.value.status]||task.value.status));const progressTitle=computed(()=>task.value.status==='waiting'?'已准备生成提示词':task.value.status==='queued'?'任务正在排队':'智能体正在生成资源')
async function load(){loading.value=true;error.value='';try{task.value=taskFromPayload(await getTask(route.params.taskId));if(isActive.value){trackTask(task.value);schedule()}await loadFeedback()}catch(e){error.value=e.message}finally{loading.value=false}}
function schedule(){clearTimeout(timer);if(!isActive.value)return;timer=setTimeout(async()=>{try{task.value=taskFromPayload(await getTask(route.params.taskId))}catch{}schedule()},document.hidden?8000:1500)}function select(i){selectedIndex.value=i;router.replace(`/resources/task/${task.value.taskId}/item/${i}`)}
async function startVideo(){starting.value=true;error.value='';try{await startVideoTask(task.value.taskId,{model:'seedance-1.5',resolution:task.value.result?.content?.resolution||'720p'});task.value.status='queued';trackTask(task.value);schedule()}catch(e){error.value=e.message}finally{starting.value=false}}
async function loadFeedback(){try{const body=await getFeedback({taskId:route.params.taskId,limit:1});const items=body?.data?.feedbacks||body?.feedbacks||[];feedbackSaved.value=items.length>0}catch{}}
async function saveFeedback(){feedbackSaving.value=true;feedbackError.value='';try{await submitFeedback({taskId:task.value.taskId,topic:selected.value?.title||task.value.title,rating:rating.value,note:note.value,outcome:'completed',resourceType:selected.value?.type||task.value.taskType});feedbackSaved.value=true}catch(e){feedbackError.value=e.message}finally{feedbackSaving.value=false}}
onMounted(load);onBeforeUnmount(()=>clearTimeout(timer))
</script>
<style scoped>.task-head{margin-bottom:16px}.task-head h1{margin:10px 0 0;font-size:21px;line-height:1.4}.task-head p{margin:7px 0 0;color:#718078;font-size:10px}.task-progress-panel{display:grid;gap:13px;margin-bottom:16px;padding:16px;border:1px solid #d3e4db;border-left:3px solid #176f4b;border-radius:7px;background:#edf5f1}.task-progress-panel>div:first-child{display:grid;grid-template-columns:22px minmax(0,1fr) 34px;align-items:center;gap:10px;color:#176f4b}.task-progress-panel strong,.task-progress-panel small{display:block}.task-progress-panel strong{font-size:12px}.task-progress-panel small{margin-top:4px;color:#66776e;font-size:9px}.task-progress-panel b{font-size:11px}.resource-tabs{margin-bottom:14px}.feedback-panel{margin-top:20px;padding:18px;border:1px solid #dce5e0;border-top:3px solid #a16f19;border-radius:7px;background:white}.rating-row{display:flex;gap:6px;margin-bottom:12px}.rating-row button{width:44px;height:44px;display:grid;place-items:center;border:1px solid #dce5e0;border-radius:5px;background:white;color:#9aa69f}.rating-row button.active{border-color:#b58225;background:#fff8e9;color:#b58225}.rating-row button.active svg{fill:currentColor}.feedback-panel textarea{width:100%;padding:11px;border:1px solid #cfdad4;border-radius:6px;resize:vertical}.feedback-panel .primary-btn{margin-top:12px}.form-error{color:#a04435;font-size:11px}.failure-panel{display:grid;grid-template-columns:32px minmax(0,1fr);gap:10px;padding:16px;border-radius:7px;background:#fff0ec;color:#a04435}.failure-panel strong{font-size:13px}.failure-panel p{margin:5px 0 0;font-size:11px;line-height:1.6}.failure-panel .secondary-btn{grid-column:1/-1}</style>
